RELEASE_FILE = "data/releases/1.0.0/fungal_characters_v1.0.0_postgresql.sql"


def load_release(apps, schema_editor):
    """Create the character tables and data exactly as released.

    Skipped if the release is already loaded (e.g. with psql -f, as on 2026-11-25).
    """
    with schema_editor.connection.cursor() as cur:
        cur.execute("SELECT to_regclass('mr_characters') IS NOT NULL")
        if cur.fetchone()[0]:
            return
        sql = (django_settings.BASE_DIR / RELEASE_FILE).read_text(encoding="utf-8")
        cur.execute(sql)  # one transaction (BEGIN ... COMMIT) inside the file


def start_code_counters(apps, schema_editor):
    """Start FCC/FCV numbering after the highest codes in the release."""
    CodeCounter = apps.get_model("characters", "CodeCounter")
    with schema_editor.connection.cursor() as cur:
        for prefix, table in (("FCC", "mr_characters"), ("FCV", "lookup_items")):
            cur.execute(f"SELECT coalesce(max(substring(code from 4)::int), 0) FROM {table} WHERE code LIKE %s", [prefix + "%"])
            CodeCounter.objects.update_or_create(prefix=prefix, defaults={"last_number": cur.fetchone()[0]})


